<?php require 'config.php';need();$u=me();$R=role();top('Dashboard');
function stats($a){echo '<div class="grid">';foreach($a as $k=>$v)echo "<div class='stat'><small>$k</small><b>".h($v).'</b></div>';echo '</div>';}
function otab($t,$rows){echo '<div class="card"><h2>'.$t.'</h2><table><tr><th>#</th><th>Customer</th><th>Service</th><th>Site</th><th>Status</th><th>Technician</th></tr>';foreach($rows as $r)echo '<tr><td>'.$r['id'].'</td><td>'.h($r['cname']).'</td><td>'.h($r['service_type']).'</td><td>'.h($r['site_location']).'</td><td>'.badge($r['status']).'</td><td>'.h($r['tname']?:'-').'</td></tr>';echo '</table><p><a class="btn" href="orders.php">Open orders</a></p></div>';}
$b=baseq();
if($R==='customer'){$id=$u['id'];stats(['My orders'=>n('SELECT COUNT(*) FROM orders WHERE customer_id=?',[$id]),'In progress'=>n("SELECT COUNT(*) FROM orders WHERE customer_id=? AND status<>'Completed'",[$id]),'Completed'=>n("SELECT COUNT(*) FROM orders WHERE customer_id=? AND status='Completed'",[$id])]);otab('My recent orders',q($b.' WHERE o.customer_id=? ORDER BY o.id DESC LIMIT 5',[$id])->fetchAll());}
if($R==='sales'){stats(['Pending (assign technician)'=>n("SELECT COUNT(*) FROM orders WHERE status='Pending'"),'Surveyed (make sale)'=>n("SELECT COUNT(*) FROM orders WHERE status='Surveyed'"),'Low-stock items'=>n('SELECT COUNT(*) FROM products WHERE stock_qty<=reorder_level'),'Total sales'=>ugx(fin()['sales'])]);otab('Orders needing action',q($b." WHERE o.status IN('Pending','Surveyed') ORDER BY o.id")->fetchAll());}
if($R==='technician'){otab('My active assignments',q($b." WHERE o.technician_id=? AND o.status IN('Assigned','Sold') ORDER BY o.id",[$u['id']])->fetchAll());}
if($R==='ceo'){$f=fin();stats(['Orders'=>n('SELECT COUNT(*) FROM orders'),'In progress'=>n("SELECT COUNT(*) FROM orders WHERE status<>'Completed'"),'Sales revenue'=>ugx($f['sales']),'Expenditure'=>ugx($f['spend']),'Profit'=>ugx($f['profit']),'Technicians'=>n("SELECT COUNT(*) FROM users WHERE role='technician'"),'Customers'=>n("SELECT COUNT(*) FROM users WHERE role='customer'"),'Low-stock items'=>n('SELECT COUNT(*) FROM products WHERE stock_qty<=reorder_level')]);
 otab('All recent orders and sites',q($b.' ORDER BY o.id DESC LIMIT 10')->fetchAll());
 echo '<div class="card"><h2>Customers</h2><table><tr><th>Name</th><th>Contact</th><th>Location</th><th>Orders</th></tr>';foreach(q("SELECT u.*,(SELECT COUNT(*) FROM orders WHERE customer_id=u.id) c FROM users u WHERE role='customer'")->fetchAll() as $c)echo '<tr><td>'.h($c['full_name']).'</td><td>'.h($c['contact']).'</td><td>'.h($c['location']).'</td><td>'.$c['c'].'</td></tr>';echo '</table></div>';
 echo '<div class="card"><h2>Stock needing reorder</h2><table><tr><th>Product</th><th>Stock</th><th>Reorder at</th></tr>';foreach(q('SELECT * FROM products WHERE stock_qty<=reorder_level')->fetchAll() as $p)echo '<tr><td>'.h($p['name']).'</td><td>'.$p['stock_qty'].'</td><td>'.$p['reorder_level'].'</td></tr>';echo '</table><p><a class="btn k" href="inventory.php">Inventory & finance</a> <a class="btn k" href="technicians.php">Technicians</a> <a class="btn k" href="reviews.php">Reviews</a></p></div>';}
bottom();
